import { ReactNode } from 'react';

import { StylingProps } from '../../../core/types/styling-props.js';
import { TruncationMode } from '../../../typography/TextEllipsis.js';
import { ChartMessage } from '../../core/types/chart-message.js';
import {
  CustomColorPalette,
  ColorPalette,
} from '../../core/types/color-palette.js';
import { ValueRepresentation } from '../../core/types/scales.js';
import { SeriesCurve, Timeseries } from '../../core/types/timeseries.js';

/** options for choosing the chart variant */
export const chartVariantOptions = ['line', 'area', 'bar'] as const;

/** Type of the chart that will be displayed in a timeseries */
export type ChartVariant = (typeof chartVariantOptions)[number];

/** Props for the timeseries chart */
export interface TimeseriesChartProps extends StylingProps {
  /**
   * The series data passed to the chart
   */
  data?: Timeseries[];
  /** The height of the chart. If a number is passed, it will be treated as px.
   * @defaultValue 300px
   */
  height?: number | string;
  /**
   * Variant to configure the type of chart
   * @defaultValue 'line'
   */
  variant?: ChartVariant;
  /** Exposed callback to display series actions for a series  */
  seriesActions?: (timeseries: unknown) => React.ReactElement;
  /** Messages emitted by the chart */
  onMessage?: (messages: ChartMessage[]) => void;
  /** The gap policy to be applied to all series of the chart */
  gapPolicy?: GapPolicy;
  /**
   * Show the datapoints always, never or based on a threshold amount.
   * @defaultValue 'auto
   * */
  pointsDisplay?: PointsDisplay;
  /** The value representation to be used, either absolute or relative */
  valueRepresentation?: ValueRepresentation;
  /** Show the loading indicator when truly.
   * @defaultValue false
   */
  loading?: boolean;
  /**
   * Color palette that will be applied to the chart.
   * @defaultValue 'categorical'
   */
  colorPalette?: ColorPalette | CustomColorPalette;
  /**
   * Truncation mode to use (start, middle, end)
   * Applied to all the parts that truncate text.
   * @defaultValue 'middle'
   */
  truncationMode?: TruncationMode;
  /** Defines the curve shape of the series
   * @defaultValue 'linear'
   */
  curve?: SeriesCurve;

  children?: ReactNode;
}

/** Time unit for time threshold expression */
export type TimeUnit = 'ms' | 's' | 'min' | 'h' | 'd' | 'mo' | 'y';

/** Time threshold expression. Example: 10min */
export type TimeThreshold = `${number}${TimeUnit}`;

/** A gap policy configuration that includes a threshold */
export type ThresholdGapPolicy = {
  threshold: TimeThreshold;
};

/** Whether to show gaps or interpolate "gap data points" between data points */
export type GapPolicy = 'gap' | 'connect' | ThresholdGapPolicy;

/** Whether to show data points always, never, or depending on a width-based threshold amount */
export const pointsDisplayOptions = ['always', 'never', 'auto'] as const;
export type PointsDisplay = (typeof pointsDisplayOptions)[number];
